import mongoose from "mongoose";
import Product from "./product.model.js";
import ApiError from "../../utils/Apierror.js";
import { deleteCloudinaryImage } from "../../utils/cloudinary.js";
import sendSuccessResponse from "../../utils/ApiResponse.js";
import Category from "../categories/category.model.js";
import {
    validateProduct,
    validateProductUpdate,
} from "./product.validation.js";

// Create a new product
export const createProduct = async (req, res, next) => {
    try {
        // Get the image URLs generated by Cloudinary.
        //
        // Each uploaded file contains a `path` property,
        // which is the Cloudinary URL.
        const imageUrls = req.files?.map(
            (file) => file.path
        ) || [];

        // Put the Cloudinary URLs into req.body.images
        // so the existing validation and Product model
        // can continue using the `images` field.
        req.body.images = imageUrls;

        // Convert numeric fields because multipart/form-data
        // sends text values as strings.
        req.body.price = Number(req.body.price);
        req.body.discount = Number(req.body.discount || 0);
        req.body.stock = Number(req.body.stock);
        // ==========================================
        // CONVERT TAGS FROM FORM-DATA
        // ==========================================

        // FormData sends tags as a string.
        // Example:
        // "romper,baby clothing,cotton"
        //
        // Convert that string into an array.
        if (typeof req.body.tags === "string") {
            req.body.tags = req.body.tags
                .split(",")
                .map((tag) => tag.trim())
                .filter(Boolean);
        }
        // Validate the product data from the request
        const error = validateProduct(req.body);

        if (error) {
            return next(new ApiError(400, error));
        }
        // Check that the category exists and is active
        const categoryDoc = await Category.findOne({
            _id: req.body.category,
            isActive: true
        });

        if (!categoryDoc) {
            return next(
                new ApiError(400, "Category not found or inactive")
            );
        }

        // Get the product fields from the request body
        const {
            title,
            description,
            price,
            discount,
            category,
            brand,
            ageGroup,
            images,
            stock,
            tags
        } = req.body;

        // Create a new product document
        const product = new Product({
            title: title.trim(),
            description: description.trim(),
            price,
            discount: discount ?? 0,
            category: category,
            brand: brand.trim(),
            ageGroup: ageGroup.trim(),
            images,
            stock,
            tags: tags ?? []
        });

        // Save the product to MongoDB
        await product.save();

        // Load the category information for the response
        await product.populate("category");


        // Send the created product to the client
        sendSuccessResponse(
            res,
            201,
            product,
            "Product created successfully"
        );

    } catch (error) {
        // Pass unexpected errors to the centralized error handler
        next(error);
    }
};

// Get all products

/**
 * Get products with search, filters, and pagination.
 *
 * Supported query parameters:
 * search, category, ageGroup, brand,
 * minPrice, maxPrice, inStock, page, limit
 */
export const getProducts = async (req, res, next) => {
    try {
        // Read the filters from the URL query parameters.
        const {
            page = 1,
            limit = 10,
            search = "",
            category,
            ageGroup,
            brand,
            minPrice,
            maxPrice,
        } = req.query;

        // Convert pagination values to numbers.
        const pageNumber = Number(page);
        const limitNumber = Number(limit);

        // Validate pagination to prevent invalid database queries.
        if (
            !Number.isInteger(pageNumber) ||
            pageNumber < 1 ||
            !Number.isInteger(limitNumber) ||
            limitNumber < 1 ||
            limitNumber > 100
        ) {
            return next(
                new ApiError(
                    400,
                    "Page must be positive and limit must be between 1 and 100"
                )
            );
        }

        // Validate optional price filters.
        const minimumPrice =
            minPrice !== undefined && minPrice !== ""
                ? Number(minPrice)
                : undefined;

        const maximumPrice =
            maxPrice !== undefined && maxPrice !== ""
                ? Number(maxPrice)
                : undefined;

        if (
            (minimumPrice !== undefined &&
                (!Number.isFinite(minimumPrice) || minimumPrice < 0)) ||
            (maximumPrice !== undefined &&
                (!Number.isFinite(maximumPrice) || maximumPrice < 0))
        ) {
            return next(
                new ApiError(
                    400,
                    "Minimum and maximum prices must be valid non-negative numbers"
                )
            );
        }

        if (
            minimumPrice !== undefined &&
            maximumPrice !== undefined &&
            minimumPrice > maximumPrice
        ) {
            return next(
                new ApiError(
                    400,
                    "Minimum price cannot exceed maximum price"
                )
            );
        }

        // Calculate how many products to skip.
        const skip = (pageNumber - 1) * limitNumber;

        // Build one MongoDB filter from all selected criteria.
        const filter = {};

        // Search product titles without case sensitivity.
        if (search.trim()) {
            filter.title = {
                $regex: search.trim(),
                $options: "i",
            };
        }

        // Filter by category ID.
        if (category && category.trim()) {
            if (!mongoose.Types.ObjectId.isValid(category.trim())) {
                return next(
                    new ApiError(400, "Invalid category ID")
                );
            }

            filter.category = category.trim();
        }

        // Filter by the product's age group.
        if (ageGroup && ageGroup.trim()) {
            filter.ageGroup = {
                $regex: `^${ageGroup.trim()}$`,
                $options: "i",
            };
        }
 // Filter age groups by partial text while the user types.
if (ageGroup && ageGroup.trim()) {
    // Escape special characters so the input is treated as plain text.
    const safeAgeGroup = ageGroup.trim().replace(
        /[.*+?^${}()|[\]\\]/g,
        "\\$&"
    );

    filter.ageGroup = {
        $regex: safeAgeGroup,
        $options: "i", // Ignore uppercase/lowercase differences.
    };
}


        // Match part of a brand name, ignoring letter case.
        // For example, "ti", "tiny", and "TINY" match "tinynest".
        if (brand && brand.trim()) {
            // Escape special regex characters so user input is treated as text.
            const safeBrand = brand.trim().replace(
                /[.*+?^${}()|[\]\\]/g,
                "\\$&"
            );

            filter.brand = {
                $regex: safeBrand,
                $options: "i",
            };
        }

        // Filter by the original product price.
        if (
            minimumPrice !== undefined ||
            maximumPrice !== undefined
        ) {
            filter.price = {};

            if (minimumPrice !== undefined) {
                filter.price.$gte = minimumPrice;
            }

            if (maximumPrice !== undefined) {
                filter.price.$lte = maximumPrice;
            }
        }

        // Public requests hide out-of-stock products.
        // The protected admin route can retrieve every product.
        if (req.originalUrl.includes("/admin")) {
            // Do not apply a stock filter for admin requests.
        } else {
            filter.stock = { $gt: 0 };
        }

        // Fetch matching products and their total count together.
        const [products, totalProducts] = await Promise.all([
            Product.find(filter)
                .populate("category")
                .sort({ createdAt: -1 })
                .skip(skip)
                .limit(limitNumber),

            Product.countDocuments(filter),
        ]);

        // Calculate the number of result pages.
        const totalPages = Math.ceil(
            totalProducts / limitNumber
        );

        // Return products and pagination metadata.
        sendSuccessResponse(
            res,
            200,
            {
                products,
                pagination: {
                    currentPage: pageNumber,
                    limit: limitNumber,
                    totalProducts,
                    totalPages,
                },
            },
            "Products fetched successfully"
        );
    } catch (error) {
        // Pass unexpected errors to the central error handler.
        next(error);
    }
};


// Get a single product by its ID
export const getProductById = async (req, res, next) => {
    try {
        // Get the product ID from the URL
        const { id } = req.params;

        // Check whether the ID has a valid MongoDB format
        if (!mongoose.Types.ObjectId.isValid(id)) {
            return next(
                new ApiError(400, "Invalid product ID")
            );
        }

        // Find the product in MongoDB
        const product = await Product.findById(id)
            .populate("category");

        // Return an error if the product doesn't exist
        if (!product) {
            return next(
                new ApiError(404, "Product not found")
            );
        }

        // Return the requested product
        sendSuccessResponse(
            res,
            200,
            product,
            "Product fetched successfully"
        );

    } catch (error) {
        // Pass unexpected errors to the centralized error handler
        next(error);
    }
};

// Update an existing product
export const updateProduct = async (req, res, next) => {
    try {
        // Get product ID from the URL
        const { id } = req.params;

        // Check whether the ID is valid
        if (!mongoose.Types.ObjectId.isValid(id)) {
            return next(
                new ApiError(400, "Invalid product ID")
            );
        }

        // Convert numeric form-data values to numbers
        if (req.body.price !== undefined) {
            req.body.price = Number(req.body.price);
        }

        if (req.body.discount !== undefined) {
            req.body.discount = Number(
                req.body.discount || 0
            );
        }

        if (req.body.stock !== undefined) {
            req.body.stock = Number(req.body.stock);
        }

        // Convert comma-separated tags into an array
        if (typeof req.body.tags === "string") {
            req.body.tags = req.body.tags
                .split(",")
                .map((tag) => tag.trim())
                .filter(Boolean);
        }

        // Find the existing product
        const product = await Product.findById(id);

        if (!product) {
            return next(
                new ApiError(404, "Product not found")
            );
        }

        /*
         * Get the images that the admin wants to keep.
         *
         * AdminEditProduct sends these as JSON:
         *
         * existingImages = [
         *   "image1",
         *   "image3"
         * ]
         */
        let existingImages = product.images;

        if (req.body.existingImages) {
            try {
                existingImages = JSON.parse(
                    req.body.existingImages
                );
            } catch (error) {
                return next(
                    new ApiError(
                        400,
                        "Invalid existingImages data"
                    )
                );
            }
        }

        /*
         * Find which old images were removed.
         *
         * Example:
         *
         * Old images:
         * [image1, image2, image3]
         *
         * Remaining images:
         * [image1, image3]
         *
         * Removed images:
         * [image2]
         */
        const removedImages = product.images.filter(
            (oldImage) =>
                !existingImages.includes(oldImage)
        );



        // Get newly uploaded Cloudinary image URLs
        const newImageUrls =
            req.files?.map((file) => file.path) || [];

        /*
         * Combine:
         *
         * Existing images that were kept
         * +
         * Newly uploaded images
         */
        const finalImages = [
            ...existingImages,
            ...newImageUrls,
        ];

        // Maximum 5 images per product
        if (finalImages.length > 5) {
            return next(
                new ApiError(
                    400,
                    "A product can have a maximum of 5 images"
                )
            );
        }

        // Product must have at least one image
        if (finalImages.length === 0) {
            return next(
                new ApiError(
                    400,
                    "At least one product image is required"
                )
            );
        }

        // Set final image list
        req.body.images = finalImages;

        // Remove helper field before validation/update
        delete req.body.existingImages;

        /*
         * Validate the updated product data.
         */
        // Validate the updated product data
        const error = validateProductUpdate(req.body);

        if (error) {
            return next(
                new ApiError(400, error)
            );
        }

        // If category is being changed, verify it exists
        if (req.body.category) {
            const category =
                await Category.findOne({
                    _id: req.body.category,
                    isActive: true,
                });

            if (!category) {
                return next(
                    new ApiError(
                        400,
                        "Invalid or inactive category"
                    )
                );
            }
        }

        /*
         * Update only the fields allowed for a product.
         */
        const allowedFields = [
            "title",
            "description",
            "price",
            "discount",
            "category",
            "brand",
            "ageGroup",
            "images",
            "stock",
            "tags",
        ];

        allowedFields.forEach((field) => {
            if (req.body[field] !== undefined) {
                product[field] = req.body[field];
            }
        });

        // Save updated product
        // Save updated product
        await product.save();

        /*
         * MongoDB update was successful.
         *
         * Now it is safe to delete the images
         * that the admin removed from the product.
         */
        for (const imageUrl of removedImages) {
            await deleteCloudinaryImage(imageUrl);
        }

        // Populate category information
        await product.populate("category");

        // Send success response
        sendSuccessResponse(
            res,
            200,
            product,
            "Product updated successfully"
        );

    } catch (error) {
        // Pass unexpected errors to the error handler
        next(error);
    }
};
// Delete an existing product
export const deleteProduct = async (req, res, next) => {
    try {
        // Get the product ID from the URL
        const { id } = req.params;

        // Check whether the ID has a valid MongoDB format
        if (!mongoose.Types.ObjectId.isValid(id)) {
            return next(
                new ApiError(400, "Invalid product ID")
            );
        }

        // Find the product first
        const product = await Product.findById(id);

        // Return an error if the product doesn't exist
        if (!product) {
            return next(
                new ApiError(404, "Product not found")
            );
        }

        /*
         * Delete all product images from Cloudinary.
         *
         * product.images contains the Cloudinary URLs.
         */
        for (const imageUrl of product.images) {
            await deleteCloudinaryImage(imageUrl);
        }

        // Delete the product from MongoDB
        await Product.findByIdAndDelete(id);

        // Send a successful response
        sendSuccessResponse(
            res,
            200,
            null,
            "Product deleted successfully"
        );

    } catch (error) {
        // Pass unexpected errors to the centralized error handler
        next(error);
    }
};